int mbedtls2_version_check_feature(const char *feature) {
  const char *const *idx = features;

  if (*idx == NULL)
    return (-2);

  if (feature == NULL)
    return (-1);

  while (*idx != NULL) {
    if (!strcmp(*idx, feature))
      return (0);
    idx++;
  }
  return (-1);
}

